        /* νƒ€μ… μ£Όμ„λ§ λ²—κΈ΄λ‹¤. μ΄ μ΅°κ°μ— μλ” κ²ƒμ€ λ‹¤μ„― κ°€μ§€λΏμ΄κ³ 
           (μ•„λ κ²€μ‚¬κ°€ λ‚¨μ€ κ² μ—†μμ„ κ°•μ ν•λ‹¤), κ°μ²΄ λ¦¬ν„°λ΄μ `ν‚¤:κ°’`κ³Ό
           κ²ΉμΉμ§€ μ•λ”λ‹¤ β€” `:any`Β·`:number`Β·`:Promise<β€¦>`λ§ μ§€μ΄λ‹¤. */
        const body = cut('const autoGate=useRef', 'const resumePendingAuto=')
          .replace('const inAutoGate=<T,>(fn:()=>Promise<T>):Promise<T>=>', 'const inAutoGate=(fn)=>')
